use xiom.io;

use xiom.string;
type Account = {
  balance: Float64;
  invariant: balance >= 0.0;
}

fn transfer(from: &mut Account, to: &mut Account, amount: Float64) -> Result[Str, Str]
  requires: amount > 0.0;
  requires: amount <= from.balance;
{
  from.balance = from.balance - amount;
  to.balance = to.balance + amount;
  return Ok("Transfer of " + string.float_to_str(amount) + " complete");
}

fn main() -> Int {
  var alice = Account { balance: 1000.0 };
  var bob = Account { balance: 500.0 };

  match transfer(&mut alice, &mut bob, 200.0) {
    Ok(msg) => { io.println(msg.to_str()); return 200; }
    Err(e) => { io.println(e.to_str()); return 400; }
  }
}
